/**
 * Benchmark fixtures for NFR-P-01, P-02 and P-08 (M2 plan D7), generated from
 * a fixed seed so the committed files can be regenerated byte for byte:
 *
 *   node scripts/gen-bench-fixtures.mjs          writes fixtures/bench/*.json
 *   node scripts/gen-bench-fixtures.mjs --check  exits 1 if a committed file differs
 *
 * Shaped by S0 (`docs/00-s0-instrument-survey.md`): real instruments are either
 * small and conditional or large and flat, and choice, group and display make
 * up three quarters of all items. Every fixture carries the same five-link
 * chain, `chain-1` → … → `chain-6`, which is NFR-P-02's "cascade depth 5".
 *
 * - `small-25`: the median, 25 items, conditional (the case a clinic meets all day).
 * - `large-500`: the p90, 500 items, mostly flat, nested to depth 6.
 * - `ceiling`: **synthetic**, every NFR-P-04/P-05 limit at once: 1,000 items,
 *   500 conditions, a 20-item repeating group meant to hold 50 instances,
 *   group nesting 10 and a chain of 10. No real instrument is this; S0 says so.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));

/** Park–Miller, so the sequence is the same on every platform and Node version. */
export function random(seed) {
  let state = seed;
  return () => (state = (state * 48_271) % 2_147_483_647) / 2_147_483_647;
}

const coding = (code) => ({ system: 'urn:fhirq:bench', code });
const options = (count) => Array.from({ length: count }, (_, i) => ({ valueCoding: coding(`o${i}`) }));
const yes = (question) => ({ question, operator: '=', answerBoolean: true });

/** A leaf item of a type drawn from S0's mix. */
function leaf(next, linkId) {
  const roll = next();
  if (roll < 0.55) return { linkId, text: linkId, type: 'choice', answerOption: options(2 + Math.floor(next() * 6)) };
  if (roll < 0.7) return { linkId, text: linkId, type: 'display' };
  if (roll < 0.82) return { linkId, text: linkId, type: 'decimal' };
  if (roll < 0.92) return { linkId, text: linkId, type: 'string' };
  if (roll < 0.95) return { linkId, text: linkId, type: 'text' };
  if (roll < 0.98) return { linkId, text: linkId, type: 'date' };
  return { linkId, text: linkId, type: 'boolean' };
}

/** `chain-1` → `chain-(links+1)`: each link is a boolean enabled by the previous one answering yes. */
function chain(links) {
  return Array.from({ length: links + 1 }, (_, i) => ({
    linkId: `chain-${i + 1}`,
    text: `Chain ${i + 1}`,
    type: 'boolean',
    ...(i === 0 ? {} : { enableWhen: [yes(`chain-${i}`)] }),
  }));
}

const questionnaire = (name, item) => ({
  resourceType: 'Questionnaire',
  url: `urn:fhirq:bench:${name}`,
  version: '1',
  status: 'draft',
  title: `Benchmark fixture: ${name}`,
  item,
});

function small() {
  const next = random(25);
  return questionnaire('small-25', [
    { linkId: 'consent', text: 'Consent', type: 'boolean' },
    ...chain(5),
    {
      linkId: 'history',
      text: 'History',
      type: 'group',
      enableWhen: [yes('consent')],
      item: [leaf(next, 'h1'), leaf(next, 'h2'), leaf(next, 'h3'), { linkId: 'smoker', text: 'Smoker', type: 'boolean' }],
    },
    { linkId: 'smoking', text: 'Smoking', type: 'group', enableWhen: [yes('smoker')], item: [leaf(next, 's1'), leaf(next, 's2')] },
    {
      linkId: 'meds',
      text: 'Medications',
      type: 'group',
      repeats: true,
      item: [
        { linkId: 'med-name', text: 'Name', type: 'string' },
        { linkId: 'med-taking', text: 'Taking', type: 'boolean' },
        { linkId: 'med-dose', text: 'Dose', type: 'string', enableWhen: [yes('med-taking')] },
      ],
    },
    { linkId: 'either', text: 'Either', type: 'string', enableBehavior: 'any', enableWhen: [yes('consent'), yes('smoker')] },
    leaf(next, 'f1'),
    leaf(next, 'f2'),
    leaf(next, 'f3'),
    leaf(next, 'f4'),
    leaf(next, 'f5'),
  ]);
}

/** Groups nested `depth` deep with `leaves` items spread over them. */
function nested(next, prefix, depth, leaves, extra = []) {
  const perLevel = Math.floor(leaves / depth);
  let inner = [...extra];
  for (let level = depth; level >= 1; level -= 1) {
    const count = level === 1 ? leaves - perLevel * (depth - 1) : perLevel;
    const items = Array.from({ length: count }, (_, i) => leaf(next, `${prefix}-${level}-${i}`));
    inner = [{ linkId: `${prefix}-g${level}`, text: `${prefix} ${level}`, type: 'group', item: [...items, ...inner] }];
  }
  return inner;
}

function large() {
  const next = random(500);
  const gates = Array.from({ length: 8 }, (_, i) => ({ linkId: `gate-${i}`, text: `Gate ${i}`, type: 'boolean' }));
  const gated = Array.from({ length: 14 }, (_, i) => ({ ...leaf(next, `gated-${i}`), enableWhen: [yes(`gate-${i % 8}`)] }));
  const meds = {
    linkId: 'meds',
    text: 'Medications',
    type: 'group',
    repeats: true,
    item: Array.from({ length: 13 }, (_, i) => leaf(next, `med-${i}`)),
  };
  // 6 chain + 8 gates + 14 gated + 1 repeat group + 13 in it + 10 section groups + 448 leaves = 500 items.
  const sections = Array.from({ length: 5 }, (_, s) => nested(next, `sec${s}`, s === 0 ? 6 : 1, s === 0 ? 100 : 87)).flat();
  return questionnaire('large-500', [...chain(5), ...gates, ...gated, meds, ...sections]);
}

function ceiling() {
  const next = random(1000);
  const gates = Array.from({ length: 40 }, (_, i) => ({ linkId: `gate-${i}`, text: `Gate ${i}`, type: 'boolean' }));
  // 11 chain items carry 10 conditions; 40 gates; 440 gated leaves carry 440 conditions.
  const gated = Array.from({ length: 440 }, (_, i) => ({ ...leaf(next, `gated-${i}`), enableWhen: [yes(`gate-${i % 40}`)] }));
  // A 20-item repeating group: 10 triggers, each enabling one sibling in the same instance, 50 conditions with the rest.
  const repeat = {
    linkId: 'visit',
    text: 'Visit',
    type: 'group',
    repeats: true,
    item: Array.from({ length: 20 }, (_, i) =>
      i % 2 === 0
        ? { linkId: `visit-${i}`, text: `Visit ${i}`, type: 'boolean' }
        : { ...leaf(next, `visit-${i}`), enableWhen: [yes(`visit-${i - 1}`)] },
    ),
  };
  // 11 + 40 + 440 + 21 = 512 items and 460 conditions so far. Nesting 10 deep holds the remaining 488 items;
  // 40 of them carry a condition on a gate, which brings the total to 500.
  const deep = nested(next, 'deep', 10, 478);
  let conditioned = 0;
  const walk = (items) => {
    for (const item of items) {
      if (item.type !== 'group' && conditioned < 40) {
        item.enableWhen = [yes(`gate-${conditioned % 40}`)];
        conditioned += 1;
      }
      if (item.item) walk(item.item);
    }
  };
  walk(deep);
  return questionnaire('ceiling', [...chain(10), ...gates, ...gated, repeat, ...deep]);
}

export const FIXTURES = { 'small-25': small, 'large-500': large, ceiling };

/** The small fixture is indented for reading; the two large ones are one line each, since nobody reads them. */
export function render(name) {
  return `${JSON.stringify(FIXTURES[name](), null, name === 'small-25' ? 2 : undefined)}\n`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const check = process.argv.includes('--check');
  let stale = false;
  for (const name of Object.keys(FIXTURES)) {
    const path = `${root}fixtures/bench/${name}.json`;
    const text = render(name);
    if (check) {
      let committed = '';
      try {
        committed = readFileSync(path, 'utf8');
      } catch {
        committed = '';
      }
      if (committed !== text) {
        console.error(`stale: fixtures/bench/${name}.json`);
        stale = true;
      }
    } else {
      writeFileSync(path, text);
      console.log(`wrote fixtures/bench/${name}.json`);
    }
  }
  if (stale) process.exit(1);
}
